const items = $input.all();
const result = [];

for (const item of items) {
  const data = item.json;


  if (!data.ticket_id || !data.message || !data.product) {
    result.push({
      json: {
        ticket_id: data.ticket_id || null,
        execution_status: 'Failed',
        error_message: 'Missing required fields (ticket_id, message, or product)',
        timestamp: new Date().toISOString(),
        is_valid: false
      }
    });
  } else {

    let email = (data.customer_email || '').trim().toLowerCase();
    if (email.endsWith('@gmail.com')) {
      const [local, domain] = email.split('@');
      const cleanLocal = local.split('+')[0];
      email = `${cleanLocal}@${domain}`;
    }
    data.customer_email_normalized = email;
    data.is_valid = true;
    result.push({ json: data });
  }
}

return result;

const item = $input.item.json;
const subs = item.subscriptions || [];
const matchingSubs = subs.filter(s => s.product === item.product);
const activeSubs = matchingSubs.filter(s => s.status === 'active');

let status = 'not_executed';
let reason = null;

if (activeSubs.length === 1) {
  status = 'simulated_success';
} else if (activeSubs.length > 1) {
  status = 'requires_review';
  reason = 'Multiple active subscriptions found';
} else {
  status = 'not_executed';
  reason = 'No active matching subscription found';
}

return {
  json: {
    ...item,
    matching_subscription_count: matchingSubs.length,
    action_type: 'cancellation',
    action_status: status,
    details: { reason }
  }
};

const items = $input.all();

return items.map(item => {
  const data = item.json;
  const subs = data.subscriptions || [];
  const matchingSubs = subs.filter(s => s.product === data.product);

  let status = 'not_executed';
  let reason = null;

  if (matchingSubs.length >= 1) {
    status = 'simulated_success';
  } else {
    status = 'not_executed';
    reason = 'No matching subscription for product';
  }

  return {
    json: {
      ...data,
      matching_subscription_count: matchingSubs.length,
      action_type: 'cancellation_with_billing_clarification',
      action_status: status,
      details: { reason }
    }
  };
});

