const item = $input.item.json;
const kb = [
  { topic: 'freezing', response_context: 'Ask the customer to update the app, restart the device, and retry.' },
  { topic: 'login', response_context: 'Ask the customer to verify the account email and reset the password.' }
];

const msg = (item.message || '').toLowerCase();
const matchedKb = kb.find(k => msg.includes(k.topic));

let status = 'simulated_success';
let reason = null;
let context = null;

if (matchedKb) {
  context = matchedKb.response_context;
} else {
  status = 'requires_review';
  reason = 'No matching knowledge base troubleshooting topic found';
}

return {
  json: {
    ...item,
    matching_subscription_count: (item.subscriptions || []).filter(s => s.product === item.product).length,
    action_type: 'technical_issue',
    action_status: status,
    troubleshooting_context: context,
    details: { reason, troubleshooting_context: context }
  }
};

const item = $input.item.json;
return {
  json: {
    ...item,
    matching_subscription_count: (item.subscriptions || []).filter(s => s.product === item.product).length,
    action_type: 'other',
    action_status: 'queued',
    details: { reason: 'General inquiry queued for manual support review' }
  }
};

const items = $input.all();
const logs = [];

for (const item of items) {
  const data = item.json;
  logs.push({
    json: {
      timestamp: new Date().toISOString(),
      ticket_id: data.ticket_id || null,
      detected_intent: data.action_type || data.intent || 'unknown',
      matching_subscription_count: data.matching_subscription_count ?? 0,
      action_type: data.action_type || null,
      action_status: data.action_status || (data.execution_status === 'Failed' ? 'failed' : 'processed'),
      execution_status: data.execution_status || 'Success',
      error_message: data.error_message || null,
      generated_response: data.generated_response || null
    }
  });
}

return logs;

const items = $input.all();
return items.map(item => {
  const msg = (item.json.message || '').toLowerCase();
  let intent = 'other';
  if (msg.includes('cancel') && msg.includes('charged')) {
    intent = 'cancellation_with_billing_clarification';
  } else if (msg.includes('cancel')) {
    intent = 'cancellation';
  } else if (msg.includes('refund') || msg.includes('money back')) {
    intent = 'refund';
  } else if (msg.includes('freezing') || msg.includes('login') || msg.includes('issue')) {
    intent = 'technical_issue';
  }
  return {
    json: {
      ...item.json,
      intent: intent,
      confidence: 0.98
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;
  let responseText = "Thank you for reaching out to PulseFit support.";

  if (data.action_status === 'simulated_success') {
    responseText = `Hello! We have successfully processed your ${data.action_type} request for PulseFit.`;
  } else if (data.action_status === 'requires_review' || data.action_status === 'queued') {
    responseText = "Hello! Your request has been logged and queued for manual review by a support representative.";
  } else if (data.action_status === 'not_executed') {
    responseText = `Hello! We were unable to auto-process your request. Reason: ${data.details?.reason || 'Validation check failed'}.`;
  }

  return {
    json: {
      ...data,
      generated_response: {
        subject: "Response regarding your PulseFit inquiry",
        message: responseText
      }
    }
  };
});
